package setup

import (
	"strings"
)

// initContactsRemoteHost reports whether a literal network command in the
// command names a target that is neither loopback nor a local path.
func initContactsRemoteHost(command string) bool {
	for _, w := range initRemoteParts(command) {
		if len(w) == 0 {
			continue
		}
		var args []string
		urlOnly := false
		switch w[0] {
		case "curl", "wget":
			args, urlOnly = w[1:], true
		case "ping", "nc", "telnet", "ssh":
			args = w[1:]
		case "git":
			if len(w) < 2 || w[1] != "ls-remote" {
				continue
			}
			args, urlOnly = w[2:], true
		default:
			continue
		}
		for _, a := range args {
			a = strings.Trim(a, `'"`)
			if initRemoteTarget(a, urlOnly, w[0] == "git") {
				return true
			}
			if !urlOnly && a != "" && !strings.HasPrefix(a, "-") && strings.Trim(a, "0123456789") != "" {
				break
			}
		}
	}
	return false
}

func initRemoteParts(command string) [][]string {
	var parts [][]string
	var words []string
	var word strings.Builder
	var quote rune
	escaped := false
	flush := func() {
		if word.Len() > 0 {
			words = append(words, word.String())
			word.Reset()
		}
	}
	for _, r := range command {
		switch {
		case escaped:
			word.WriteRune(r)
			escaped = false
		case r == '\\' && quote != '\'':
			word.WriteRune(r)
			escaped = true
		case quote != 0:
			word.WriteRune(r)
			if r == quote {
				quote = 0
			}
		case r == '\'' || r == '"':
			quote = r
			word.WriteRune(r)
		case r == ';' || r == '&' || r == '|' || r == '\n':
			flush()
			parts = append(parts, words)
			words = nil
		case r == ' ' || r == '\t':
			flush()
		default:
			word.WriteRune(r)
		}
	}
	flush()
	return append(parts, words)
}

var initLoopbackHosts = map[string]bool{"localhost": true, "127.0.0.1": true, "::1": true, "0.0.0.0": true}

func initHostOf(s string) string {
	if i := strings.LastIndex(s, "@"); i >= 0 {
		s = s[i+1:]
	}
	if i := strings.IndexAny(s, "/?#"); i >= 0 {
		s = s[:i]
	}
	if strings.HasPrefix(s, "[") {
		if i := strings.Index(s, "]"); i > 0 {
			return s[1:i]
		}
	}
	if strings.Count(s, ":") == 1 {
		s = s[:strings.Index(s, ":")]
	}
	return s
}

func initRemoteTarget(a string, urlOnly, git bool) bool {
	if a == "" || strings.HasPrefix(a, "-") {
		return false
	}
	if i := strings.Index(a, "://"); i > 0 {
		if a[:i] == "file" {
			return false
		}
		return !initLoopbackHosts[initHostOf(a[i+3:])]
	}
	if urlOnly {
		if git {
			if at := strings.Index(a, "@"); at > 0 && strings.Contains(a[at:], ":") && !strings.Contains(a[:at], "/") {
				return !initLoopbackHosts[initHostOf(a[at+1:])]
			}
		}
		return false
	}
	if a == "." || strings.HasPrefix(a, "./") || strings.HasPrefix(a, "../") || strings.HasPrefix(a, "/") {
		return false
	}
	if strings.Trim(a, "0123456789") == "" {
		return false
	}
	return !initLoopbackHosts[initHostOf(a)]
}

